int DeleteX(Lnode *&head, int x) {
  Lnode *p = head->next;
  Lnode *pre = head;
  while (p != head) {
    if (p->data == x) {
      pre->next = p->next;
      delete p;
      return 1;
    }
    pre = p;
    p = p->next;
  }
  return 0;
}

void intersection(lnode *&ha, lnode *&hb) {
  lnode *pa = ha->next, *pr = ha, *pb = hb->next, *s;
  while(pa != ha && pb != hb) {
    if(pa->data < pb->data) {
      pr = pa;
      pa = pa->next;
    } else if(pa->data == pb->data) {
      pr = pa;
      pa = pa->next;
      pb = pb->next;
    } else {
      s = new lnode;
      s->data = pb->data;
      pr->next = s;
      s->next = pa;
      pr = s;
      pb = pb->next;
    }
  }
  while(pb != hb) {
    s = new lnode;
    s->data = pb->data;
    s->next = pr->next;
    pr->next = s;
    pr = s;
    pb = pb->next;
  }
}

void inserthb(lnode *ha, lnode *&hb) {
  hb = new lnode;
  hb->next = NULL;
  lnode *p = ha->next, *qr, *q, *s;
  while(p) {
    if(p->data % 2 == 0) {
      qr = hb;
      q = hb->next;
      while(q && q->data <= p->data) {
        qr = q;
        q = q->next;
      }
      s = new lnode;
      s->data = p->data;
      s->next = q;
      qr->next = s;
    }
    p = p->next;
  }
}

void difference(LNode *heada, LNode *headb, int &n) {
  n = 0;
  LNode *p = heada->next;
  LNode *q = headb->next;
  LNode *pre = heada, *u;
  while (p != NULL && q != NULL) {
    if (p->data < q->data) {
      pre = p;
      p = p->next;
      n++;
    } else if (p->data > q->data) {
      q = q->next;
    } else {
      pre->next = p->next;
      u = p;
      p = p->next;
      delete u;
    }
  }
  while (p != NULL) {
    n++;
    p = p->next;
  }
}

int hightbitree(BitNode* t) {
  if (t == NULL) return 0;
  int lh = hightbitree(t->lchild);
  int rh = hightbitree(t->rchild);
  return (lh > rh ? lh : rh) + 1;
}

// 递归算法
BITNode *FindMin(BITNode *t) {
  if(t == NULL) return t;
  else if(t->lchild == NULL) return t;
  else return FindMin(t->lchild);
}
// 非递归算法
BITNode *FindMinIter(BITNode *t) {
  if(t != NULL)
    while(t->lchild != NULL)
      t = t->lchild;
  return t;
}

